#!/usr/bin/env python3
"""Run a command with selectable tty-ness of stdin/stdout/stderr.

usage: ttyrun.py <spec> -- cmd...
spec is 3 chars for fd 0,1,2:  t = pty, p = pipe
Prints captured output per-fd with markers.
"""
import os, pty, select, subprocess, sys

spec = sys.argv[1]
assert sys.argv[2] == "--"
cmd = sys.argv[3:]

masters = {}
kwargs = {}
names = {0: "stdin", 1: "stdout", 2: "stderr"}
child_fds = {}
for fd in (0, 1, 2):
    if spec[fd] == "t":
        m, s = pty.openpty()
        masters[fd] = m
        child_fds[fd] = s
    else:
        r, w = os.pipe()
        if fd == 0:
            child_fds[fd] = r
            masters[fd] = w
        else:
            child_fds[fd] = w
            masters[fd] = r

pid = os.fork()
if pid == 0:
    for fd in (0, 1, 2):
        os.dup2(child_fds[fd], fd)
    for f in list(masters.values()) + list(child_fds.values()):
        try:
            if f > 2:
                os.close(f)
        except OSError:
            pass
    os.execv(cmd[0], cmd)

for fd in (0, 1, 2):
    os.close(child_fds[fd])
# close stdin master so child sees EOF
os.close(masters[0])
del masters[0]

buf = {1: b"", 2: b""}
open_fds = {masters[1]: 1, masters[2]: 2}
while open_fds:
    r, _, _ = select.select(list(open_fds), [], [], 10)
    if not r:
        break
    for m in r:
        try:
            data = os.read(m, 65536)
        except OSError:
            data = b""
        if not data:
            del open_fds[m]
            try:
                os.close(m)
            except OSError:
                pass
        else:
            buf[open_fds[m]] += data
_, status = os.waitpid(pid, 0)
rc = os.waitstatus_to_exitcode(status)
for fd in (1, 2):
    sys.stdout.write("===FD%d(%s)===\n" % (fd, "tty" if spec[fd] == "t" else "pipe"))
    sys.stdout.write(repr(buf[fd]) + "\n")
sys.stdout.write("===EXIT=%d===\n" % rc)
